181: **Update handler:**
182: 
183: ```rust
184: EditorMsg::SelectWord => {
185:     let doc = model.document().clone();
186:     {
187:         let editor = model.editor_mut();
188: 
189:         for i in 0..editor.cursors.len() {
190:             if let Some((_word, start, end)) = editor.word_under_cursor_at(&doc, i) {
191:                 editor.selections[i].anchor = start;
