193:                 editor.cursors[i].line = end.line;
194:                 editor.cursors[i].column = end.column;
195:                 editor.cursors[i].desired_column = None;
196:             }
197:             // If no word under cursor (whitespace), leave unchanged
198:         }
199: 
200:         editor.merge_overlapping_selections();
201:     }
202: 
203:     model.ensure_cursor_visible();
