219: ### Phase 4: Multi-cursor `SelectLine`
220: 
221: **Update handler:**
222: 
223: ```rust
224: EditorMsg::SelectLine => {
225:     let doc = model.document().clone();
226:     {
227:         let editor = model.editor_mut();
228:         let total_lines = doc.line_count();
229: 
230:         for i in 0..editor.cursors.len() {
231:             let line = editor.cursors[i].line;
232:             let line_len = doc.line_length(line);
233: 
234:             let start = Position::new(line, 0);
235:             let end = if line + 1 < total_lines {
236:                 Position::new(line + 1, 0)  // Include newline
237:             } else {
238:                 Position::new(line, line_len)  // Last line
239:             };
240: 
241:             editor.selections[i].anchor = start;
242:             editor.selections[i].head = end;
243:             editor.cursors[i].line = end.line;
244:             editor.cursors[i].column = end.column;
245:             editor.cursors[i].desired_column = None;
246:         }
247: 
248:         editor.merge_overlapping_selections();
249:     }
250: 
251:     model.ensure_cursor_visible();
252:     model.reset_cursor_blink();
253:     Some(Cmd::Redraw)
254: }
255: ```
256: 
257: **Tests:**
258: 
259: - Single cursor: whole line selected
260: - Multi-cursor: different lines → both selected
261: - Multi-cursor: same line → merged to one
262: 
