265: ### Phase 5: Fix `ExtendSelectionToPosition`
266: 
267: **New behavior:** Collapse to primary cursor if multi-cursor, then extend
268: 
269: ```rust
270: EditorMsg::ExtendSelectionToPosition { line, column } => {
271:     let new_pos = Position::new(line, column);
272:     {
273:         let editor = model.editor_mut();
274: 
275:         // If multiple cursors, collapse to primary first
276:         if editor.cursors.len() > 1 {
277:             editor.cursors.truncate(1);
278:             editor.selections.truncate(1);
279:         }
280: 
281:         // Single selection semantics
282:         let sel = &mut editor.selections[0];
283:         let cur = &mut editor.cursors[0];
284: 
285:         if sel.is_empty() {
286:             sel.anchor = cur.to_position();
287:         }
288:         sel.head = new_pos;
289: 
290:         cur.line = new_pos.line;
291:         cur.column = new_pos.column;
292:         cur.desired_column = None;
293:     }
294: 
295:     model.ensure_cursor_visible();
296:     model.reset_cursor_blink();
297:     Some(Cmd::Redraw)
298: }
299: ```
300: 
301: **Tests:**
302: 
303: - Single cursor: extends selection to position
304: - Multi-cursor: collapses first, then extends
305: 
