481:     /// Invariants maintained:
482:     /// - `cursors.len() == selections.len()`
483:     /// - `cursors[i].to_position() == selections[i].head`
484:     /// - All selections are canonical (forward: anchor <= head)
485:     pub fn merge_overlapping_selections(&mut self) {
